param([switch]$Baseline)
$ErrorActionPreference='Stop';$repo=[IO.Path]::GetFullPath("$PSScriptRoot/../..");$out="$repo/build-extractors/runtime-test/core-delayed-owners/$(Get-Date -Format yyyyMMdd-HHmmss-fff)";[void][IO.Directory]::CreateDirectory($out)
& "$PSScriptRoot/Invoke-WithRuntimeDiagnostics.ps1" -EvidenceDirectory "$out/evidence" -RuntimeDirectories @($out) -Test {
 $inputs=@("$repo/src/common/Utilities/FunctionProcessor.cpp","$repo/src/common/Utilities/FunctionProcessor.h","$repo/src/common/Define.h","$repo/src/common/CompilerDefs.h","$PSScriptRoot/CoreDelayedOwnersTest.cpp","$PSScriptRoot/Test-CoreDelayedOwners.ps1","$PSScriptRoot/prepare_core_delayed_owners.py","$repo/src/server/game/AI/ScriptedAI/ScriptedCreature.cpp","$repo/src/server/game/AI/SmartScripts/SmartScript.cpp","$repo/src/server/game/AI/CoreAI/PassiveAI.cpp");$hashes=@{};foreach($file in $inputs){$hashes[$file]=(Get-FileHash $file).Hash}
 $python='C:/Users/Admin/.cache/codex-runtimes/codex-primary-runtime/dependencies/python/python.exe';$mode=if($Baseline){'baseline'}else{'fixed'};& $python -X utf8 "$PSScriptRoot/prepare_core_delayed_owners.py" $out $mode;if($LASTEXITCODE){throw 'Core source extraction differs'};
 $vs=& "${env:ProgramFiles(x86)}/Microsoft Visual Studio/Installer/vswhere.exe" -latest -products '*' -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -property installationPath
 [IO.File]::WriteAllText("$out/build.cmd","@echo off`r`ncall `"$vs/VC/Auxiliary/Build/vcvars64.bat`" >nul`r`ncl /nologo /EHsc /std:c++20 /W4 /MD /fsanitize=address /Zi $(if($Baseline){'/DCOUNTERFACTUAL'}) /I`"$out`" /I`"$repo/src/common`" /I`"$repo/src/common/Utilities`" `"$PSScriptRoot/CoreDelayedOwnersTest.cpp`" /Fe`"$out/test.exe`" /Fo`"$out/test.obj`" /Fd`"$out/compiler.pdb`" /link /INCREMENTAL:NO`r`nexit /b %errorlevel%`r`n")
 & "$out/build.cmd" *> "$out/build.log";if($LASTEXITCODE){Get-Content "$out/build.log" -Tail 12;throw 'Actual FunctionProcessor build failed'}
 [IO.File]::WriteAllText("$out/run.cmd","@echo off`r`ncall `"$vs/VC/Auxiliary/Build/vcvars64.bat`" >nul`r`n`"$out/test.exe`" %1`r`nexit /b %errorlevel%`r`n")
 $cases=@('summon','react','critter','boss')
 foreach($case in $cases){$start=[Diagnostics.ProcessStartInfo]::new();$start.FileName='cmd.exe';$start.Arguments='/d /c ""'+$out+'/run.cmd" '+$case+'"';$start.UseShellExecute=$false;$start.CreateNoWindow=$true;$start.RedirectStandardOutput=$true;$start.RedirectStandardError=$true;$owned=[Diagnostics.Process]::new();$owned.StartInfo=$start;if(!$owned.Start()){throw 'Owned test failed to launch'};$outputTask=$owned.StandardOutput.ReadToEndAsync();$errorTask=$owned.StandardError.ReadToEndAsync();$owned.WaitForExit();$exit=$owned.ExitCode;$stdout=$outputTask.Result;$stderr=$errorTask.Result;$owned.Dispose();[IO.File]::WriteAllText("$out/$case.stdout",$stdout);[IO.File]::WriteAllText("$out/$case.stderr",$stderr);@{exit=$exit;expected_counterfactual=[bool]$Baseline;stdout=(Get-FileHash "$out/$case.stdout").Hash;stderr=(Get-FileHash "$out/$case.stderr").Hash}|ConvertTo-Json|Set-Content "$out/$case-status.json";if($Baseline){if(!$exit -or ($stdout+$stderr) -notmatch 'AddressSanitizer: heap-use-after-free' -or ($stdout+$stderr) -notmatch 'ABORTING'){throw "Expected old helper ASAN failure missing:$case"};"PASS expected-broken full-helper ASAN counterfactual:$case"}elseif($exit -or $stderr.Length -or $stdout -notmatch '^PASS complete core delayed owner '){throw "Scheduler regression failed:$case"}else{$stdout.Trim()}}
 foreach($file in $inputs){if((Get-FileHash $file).Hash -ne $hashes[$file]){throw 'Scheduler source/header/fixture changed during test'}};@{inputs=$hashes;exported_source=(Get-FileHash "$out/FunctionProcessorActual.inc").Hash;exe=(Get-FileHash "$out/test.exe").Hash;baseline=[bool]$Baseline;complete_production_helpers=$true;asan=$true}|ConvertTo-Json -Depth 4|Set-Content "$out/inputs.json"
}
